package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;import android.graphics.Bitmap;import android.view.View;import android.widget.*;
final class ChatImageViewer {
 static NativeSheet show(Context c,String source){NativeSheet sheet=new NativeSheet(c,"Imagem da conversa");ChatZoomImage image=new ChatZoomImage(c);image.setBackground(AppStyle.shape(image,0xff080b12,16));image.setClipToOutline(true);sheet.body.addView(image,new LinearLayout.LayoutParams(-1,NativeSheet.dp(c,Math.min(420,Math.max(220,c.getResources().getConfiguration().screenHeightDp/2)))));LinearLayout controls=new LinearLayout(c);sheet.body.addView(controls);for(String label:new String[]{"−","Ajustar","＋"}){Button button=new Button(c);button.setText(label);button.setContentDescription(label.equals("−")?"Diminuir zoom":label.equals("＋")?"Aumentar zoom":"Ajustar imagem à tela");AppStyle.button(button,false);controls.addView(button,new LinearLayout.LayoutParams(0,-2,1));button.setOnClickListener(v->{if(label.equals("Ajustar"))image.reset();else image.zoomBy(label.equals("＋")?1.25f:.8f);});}sheet.body.addView(NativeSheet.text(c,"Use dois dedos para ampliar. Arraste para mover.",12,0xffbfc8d5));TextView status=NativeSheet.text(c,"Carregando imagem…",12,0xffc6b8ff);sheet.body.addView(status);Button retry=new Button(c);retry.setText("Tentar abrir novamente");AppStyle.button(retry,false);retry.setVisibility(View.GONE);sheet.body.addView(retry);Button save=new Button(c);save.setText("Salvar imagem");AppStyle.button(save,true);save.setEnabled(false);sheet.footer.setVisibility(View.VISIBLE);sheet.footer.addView(save);image.onReady(()->{status.setText("");save.setEnabled(true);retry.setVisibility(View.GONE);});Runnable load=()->{status.setText("Carregando imagem…");retry.setVisibility(View.GONE);AccountImageLoader.loadChatPreview(image,source,()->{status.setText("Não foi possível abrir a imagem. Tente novamente.");retry.setVisibility(View.VISIBLE);});};retry.setOnClickListener(v->load.run());String owner=SessionPreferences.get(c).getString("user_id","");save.setOnClickListener(v->{if(!(c instanceof MainActivity)||image.bitmap()==null)return;Bitmap bitmap=image.bitmap();((MainActivity)c).chooseImageDestination(uri->{if(!owner.equals(SessionPreferences.get(c).getString("user_id","")))return;save.setEnabled(false);status.setText("Salvando imagem…");java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();worker.execute(()->{String result;try(java.io.OutputStream out=c.getContentResolver().openOutputStream(uri)){if(out==null||!bitmap.compress(Bitmap.CompressFormat.PNG,100,out))throw new java.io.IOException();result="Imagem salva.";}catch(Exception error){result="Não foi possível salvar a imagem. Tente novamente.";}String text=result;((MainActivity)c).runOnUiThread(()->{if(sheet.dialog.isShowing()){status.setText(text);save.setEnabled(true);}});worker.shutdown();});});});sheet.show();load.run();return sheet;}
}
